settings.custom_liquid:
{% assign artist_app_url = metaobject.app_url.value | default: '' %}
{% assign artist_app_base_url = artist_app_url %}
{% if artist_app_base_url contains '/artist/' %}{% assign artist_app_base_url = artist_app_base_url | split: '/artist/' | first %}{% endif %}
<div
  class="artclub-artist-embed"
  data-artclub-artist-embed
  data-artclub-track-view="artist"
  data-artclub-track-impression="artist"
  data-artclub-source="shopify_artist_embed"
  {% if artist_app_url != blank %}data-artclub-app-url="{{ artist_app_url | escape }}"{% endif %}
  {% if metaobject.system.id != blank %}data-artclub-artist-metaobject-id="{{ metaobject.system.id | escape }}"{% endif %}>
</div>
{% if artist_app_base_url != blank %}<script src="{{ artist_app_base_url }}/artist-embed.js" defer></script>{% endif %}
